  body { font-family: 'Times New Roman', Times, serif; background: white; width: 297mm; height: 210mm; overflow: hidden; }

  .page {
    width: 297mm; height: 210mm;
    position: relative;
    background: white;
    display: flex; align-items: center; justify-content: center;
  }

  /* ── Bordure ornementale extérieure ── */
  .outer-border {
    position: absolute;
    inset: 4mm;
    border: 4px solid #8B4513;
    background: white;
  }

  /* ── Bordure intérieure dorée ── */
  .inner-border {
    position: absolute;
    inset: 8mm;
    border: 2px solid #c9a84c;
  }

  /* ── Motifs de coins (carrés décoratifs) ── */
  .corner-pattern {
    position: absolute;
    inset: 4mm;
    border: 0;
  }
  .corner-tl, .corner-tr, .corner-bl, .corner-br {
    position: absolute;
    width: 18mm; height: 18mm;
    border: 3px solid #8B4513;
  }
  .corner-tl { top: 0; left: 0; border-right: none; border-bottom: none; }
  .corner-tr { top: 0; right: 0; border-left: none; border-bottom: none; }
  .corner-bl { bottom: 0; left: 0; border-right: none; border-top: none; }
  .corner-br { bottom: 0; right: 0; border-left: none; border-top: none; }

  /* ── Répétition motif haut/bas ── */
  .pattern-bar-top, .pattern-bar-bottom {
    position: absolute;
    left: 18mm; right: 18mm;
    height: 8mm;
    background: repeating-linear-gradient(
      90deg,
      #8B4513 0px, #8B4513 6px,
      #c9a84c 6px, #c9a84c 9px,
      #8B4513 9px, #8B4513 12px,
      transparent 12px, transparent 14px
    );
    opacity: 0.35;
  }
  .pattern-bar-top    { top: 4mm; }
  .pattern-bar-bottom { bottom: 4mm; }

  /* ── Contenu ── */
  .content {
    position: relative;
    z-index: 10;
    width: 265mm; /* 297 - margins */
    padding: 10mm 18mm 8mm;
    text-align: center;
  }

  /* Ligne 1: Institution */
  .institution {
    font-size: 10.5pt;
    font-style: italic;
    color: #1a1a1a;
    margin-bottom: 4mm;
    letter-spacing: 0.02em;
  }

  /* Ligne 2: Verset biblique */
  .verset {
    font-size: 8.5pt;
    font-style: italic;
    color: #333;
    margin-bottom: 5mm;
    font-family: 'Times New Roman', serif;
  }

  /* Ligne 3: Logo + Mission */
  .header-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 4mm;
    padding: 0 5mm;
  }
  .logo-block {
    display: flex;
    align-items: center;
    gap: 4mm;
  }
  .logo-block img {
    height: 18mm;
    object-fit: contain;
  }
  .mission-text {
    font-size: 9pt;
    font-style: italic;
    color: #1a3a6e;
    text-align: right;
    max-width: 80mm;
    line-height: 1.6;
  }

  /* Titre DIPLAOMA */
  .title-diplaoma {
    font-family: 'Times New Roman', Times, serif;
    font-size: 36pt;
    font-weight: 900;
    color: #1a1a1a;
    letter-spacing: 0.08em;
    margin: 3mm 0 5mm;
    text-decoration: underline;
    text-underline-offset: 3px;
  }

  /* Champ Atolotra */
  .field-row {
    display: flex;
    align-items: baseline;
    justify-content: flex-start;
    margin-bottom: 2.5mm;
    gap: 3mm;
    padding: 0 6mm;
  }
  .field-label {
    font-size: 11pt;
    font-style: italic;
    color: #1a1a1a;
    white-space: nowrap;
    font-family: 'Times New Roman', serif;
  }
  .field-value {
    font-size: 12pt;
    font-style: italic;
    font-weight: 600;
    color: #0f2044;
    border-bottom: 1px solid #333;
    flex: 1;
    text-align: left;
    padding-bottom: 1px;
    font-family: 'Times New Roman', serif;
  }
  .field-value-short {
    font-size: 12pt;
    font-style: italic;
    font-weight: 700;
    color: #0f2044;
    border-bottom: 1px solid #333;
    min-width: 45mm;
    text-align: left;
    padding-bottom: 1px;
    font-family: 'Times New Roman', serif;
    font-family: 'Courier New', monospace;
    letter-spacing: 0.05em;
  }

  /* Corps du texte */
  .body-text {
    font-size: 9.5pt;
    font-style: italic;
    color: #1a1a1a;
    line-height: 1.7;
    margin: 2mm 0;
    text-align: center;
    font-family: 'Times New Roman', serif;
  }
  .body-text strong {
    font-size: 10.5pt;
    font-style: italic;
  }

  /* Zone date */
  .date-row {
    text-align: right;
    padding-right: 6mm;
    margin: 1.5mm 0;
    font-size: 9pt;
    font-style: italic;
    color: #1a1a1a;
  }

  /* Bas: Ambaratonga + Signatures */
  .footer-row {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    margin-top: 3mm;
    padding: 0 6mm;
  }

  .ambaratonga {
    text-align: left;
    max-width: 80mm;
  }
  .ambaratonga p {
    font-size: 8.5pt;
    font-style: normal;
    color: #1a1a1a;
    line-height: 1.5;
  }
  .ambaratonga .year-label {
    font-weight: 700;
    font-size: 8.5pt;
  }
  .ambaratonga .year-name {
    font-style: italic;
    font-size: 8.5pt;
  }
  .ambaratonga .lanjam-line {
    display: flex;
    align-items: baseline;
    gap: 2mm;
    margin-top: 1mm;
  }
  .lanjam-val {
    border-bottom: 1px solid #333;
    min-width: 35mm;
    font-weight: 700;
    color: #0f2044;
    font-size: 8.5pt;
    padding-bottom: 1px;
  }

  .signatures {
    display: flex;
    gap: 16mm;
    align-items: flex-start;
  }
  .sig-block {
    text-align: center;
  }
  .sig-block .sig-name {
    font-size: 8.5pt;
    font-weight: 700;
    color: #1a1a1a;
    margin-bottom: 2px;
  }
  .sig-block .sig-title {
    font-size: 7.5pt;
    font-style: italic;
    color: #444;
  }
  .sig-line {
    width: 42mm;
    border-bottom: 1px solid #333;
    margin: 6mm auto 2mm;
  }
</style>
</head>
<body>
<div class="page">

  <!-- Bordures ornementales -->
  <div class="outer-border"></div>
  <div class="inner-border"></div>
  <div class="corner-pattern">
    <div class="corner-tl"></div>
    <div class="corner-tr"></div>
    <div class="corner-bl"></div>
    <div class="corner-br"></div>
  </div>
  <div class="pattern-bar-top"></div>
  <div class="pattern-bar-bottom"></div>

  <!-- Contenu principal -->
  <div class="content">

    <!-- Institution -->
    <div class="institution">
      International Lutheran Laymen's League (I.L.L.L.) — Lutheran Hour Ministries (L.H.M)
    </div>

    <!-- Verset -->
    <div class="verset">
      <em>"Dinihonareo ny Soratra Masina, satria ataonareo fa ao aminy no anananareo fiainana mandrakizay, ary ireny no manambara Ahy;"</em>
      (Jaona 5:39)
    </div>

    <!-- Logo + Mission -->
    <div class="header-row">
      <div class="logo-block">
        <img src="${LOGO_B64}" alt="LHM Madagascar"/>
      </div>
      <div class="mission-text">
        <em>"Manambara an'i Kristy amin'ny firenena… ary mitarika<br/>ny olona ho ao amin'ny Fiangonana"</em>
      </div>
    </div>

    <!-- Titre principal -->
    <div class="title-diplaoma">DIPLAOMA</div>

    <!-- Atolotra -->
    <div class="field-row">
      <span class="field-label"><em>Atolotra an'${civilite}</em></span>
      <span class="field-value">${nomComplet}</span>
    </div>

    <!-- Laharana -->
    <div class="field-row">
      <span class="field-label"><em>Laharana :</em></span>
      <span class="field-value-short">${etudiant.numero_etudiant}</span>
    </div>

    <!-- Corps du texte -->
    <div class="body-text">
      <em>Izay nahatanteraka hatramin'ny farany ny Fampianarana Soratra Masina an-taratasy Ifandraisana<br/>
      (Cours Biblique par Correspondance) momba ny Finoana Kristiana,<br/>
      <strong>Izay iandraiketan'ny FEON'NY FILAZANTSARA.</strong></em>
    </div>

    <!-- Date -->
    <div class="date-row">
      <em>Antananarivo faha <span style="border-bottom:1px solid #333; padding-bottom:1px; min-width:40mm; display:inline-block;">&nbsp;&nbsp;${dateFormatted}&nbsp;&nbsp;</span></em>
    </div>

    <!-- Bas: Ambaratonga + Signatures -->
    <div class="footer-row">

      <div class="ambaratonga">
        <p class="year-label">${anneeNom} :</p>
        <p class="year-name">${anneeSub}</p>
        <div class="lanjam-line">
          <span style="font-size:8.5pt;font-style:normal;">Lanjam-pahaizana :</span>
          <span class="lanjam-val">${mention || '—'}</span>
        </div>
      </div>

      <div class="signatures">
        <div class="sig-block">
          <div class="sig-line"></div>
          <div class="sig-name">Pastora MAKAVELO Marcellin</div>
          <div class="sig-title">Tonia Nasionaly FiFiL</div>
        </div>
        <div class="sig-block">
          <div class="sig-line"></div>
          <div class="sig-name">ANDRIAMANJAKA Daniel</div>
          <div class="sig-title">Tale LHM</div>
        </div>
      </div>
    </div>

  </div><!-- /content -->
</div><!-- /page -->
</body>
</html>`;
